    @login_logout
    def validate_and_activate_delta_plan(self, skip_if_no_changes=False, bts_id=0):
        """
        Validate and activate delta plan with waiting for success.

        :param skip_if_no_changes: Ignore 'No content in this plan' validation error and skip activation of empty delta plan
        :param bts_id: BTS id - related to Test Line configuration
        :return: None
        """
        delta_plan_id = self.cu.get_delta_plan_list()[0]["plan_id"]
        action_id = self.cu.validate_delta_plan(delta_plan_id)["action_id"]
        try:
            self._validate_delta_plan(delta_plan_id, action_id)
        except ValidationError as validation_err:
            if skip_if_no_changes is True and validation_err.errors == 'No content in this plan. : No content in this plan.':
                logging.warning("No changes in delta plan. Skipping Activation")
                return
            else:
                raise
        activation_id = self.cu.activate_delta_plan(delta_plan_id)['operation_id']
        self._activate_delta_plan(delta_plan_id, activation_id)

    @login_logout
    def generate_delta_plan(self, plan_name, bts_id=0):
        """
        Generate delta plan via admin API.

        :param plan_name: name of plan, which is going to be created
        :return: None
        """
        gen_delta_action_id = self.cu.generate_delta_plan(plan_name)['action_id']
        gen_delta_state = self.cu.get_action_state_of_generating_delta_plan(gen_delta_action_id)

        if gen_delta_state['action_id'] == 'success':
            logging.debug('{} delta plan created'.format(gen_delta_state['plan_id']))
        else:
            logging.debug('{}'.format(gen_delta_state['error_message']))

    @login_logout
    def update_parameter_of_delta_plan(self, param_name, param_value, modify_randomly=0, dist_name=None, bts_id=0):
        """
        Update selected parameter of delta plan.
        Fix: ability to update value of parameter under complex structure, where path is e.g: cuOvlHa/0/parameter_name
        We have to provide whole path in param_name.

        :param param_name: name of parameter, which is going to be changed in SCF. Can also be a path in case of
                           parameter under complex structure, e.g: cuOvlHa/0/parameter_name
        :param param_value: value of parameter, which is going to be changed in SCF
        :param modify_randomly: set to 1 if you want to modify the string parameter randomly
        :param dist_name: (Optional) object dist name ie. "MRBTS-77030/NRBTS-30"
        :return: None
        """
        generate_status = self.cu.generate_delta_plan("plan_1")
        self._generate_delta_plan(generate_status)
        only_param_name = param_name.split("/")[-1]
        simple_param = \
            self.cu.search_parameters_of_current_plan(only_param_name)['items'][0]['parameter']['simple_parameter']
        if modify_randomly == '1' and simple_param is not None:
            prev_value = simple_param['value']
            param_value = prev_value + '_0'
        self._update_parameters_of_delta_plan(param_name, param_value, generate_status, dist_name)

    @login_logout
    def start_cu_configuration_activation_procedure(self, file_path, bts_id=0):
        """
        Start gNB CU plan activation. Use SCF which is not uploaded to CU.

        :param file_path: path to the CU's commissioning file in XML format
        :param bts_id: BTS id - related to Test Line configuration
        :return: action_id - ID of started activation procedure
        """
        plan_id = self._upload_configuration_file(file_path)
        activation_status = self.cu.plan_activation(plan_id)
        operation_id = activation_status["id"]
        return plan_id, operation_id

    @login_logout
    def wait_until_plan_activation_is_completed(self, plan_id, operation_id, bts_id=0):
        """
        Verify status of ongoing gNB CU activation operation.

        :param plan_id: id of pre-active plan
        :param operation_id: id of ongoing operation
        :param bts_id: BTS id - related to Test Line configuration
        :return: None
        """
        operation_ongoing = True
        while operation_ongoing:
            time.sleep(10)
            status = self.cu.get_operation_state_of_activating_plan(plan_id, operation_id)['status']
            logging.info('Activation status: {}'.format(status))
            if status != "ongoing":
                operation_ongoing = False
        if status == "success":
            logging.info("Activation finished with success")
        else:
            raise WrongApiException("Activation failed")

    @login_logout
    def switch_boolean_parameter(self, param_name, bts_id=0):
        """
        Update selected boolean parameter of delta plan.

        :param param_name: name of parameter, which is going to be changed in SCF
        :return: None
        """
        generate_status = self.cu.generate_delta_plan("plan_1")
        self._generate_delta_plan(generate_status)

        prev_value = \
            self.cu.search_parameters_of_current_plan(param_name)['items'][0]['parameter']['simple_parameter']['value']
        if prev_value == 'false':
            param_value = 'true'
        else:
            param_value = 'false'

        self._update_parameters_of_delta_plan(param_name, param_value, generate_status)

    @login_logout
    def delete_delta_plan_from_cu(self, bts_id=0):
        """
        Delete actual delta plan with admin API.

        :param bts_id: BTS id - related to Test Line configuration
        :return: None
        """
        try:
            delta_plan_id = self.cu.get_delta_plan_list()[0]["plan_id"]
            self.cu.delete_delta_plan(delta_plan_id)
        except ApiException as err:
            if ApiException(status=404):
                logging.info("Delta plan already deleted")
            else:
                raise WrongApiException("Expected HTTP Status: 404, but received: {}".format(err))
        except IndexError:
            logging.info("Delta plan already deleted")

    @login_logout_GUI
    def get_cu_configuration_via_GUI(self, bts_id=0, save_type=0, plan_name=None):
        """
        Download CU configuration file via GUI

        :param save_type: str, type of save
                0: Save as SCF - BTS configuration only
                1: Save as full BTS runtime configuration
                2: Save BTS runtime information only
        :param bts_id:  BTS ID - related to Test Line configuration
        :param plan_name: name of the plan which is going to be downloaded
        """
        if plan_name is not None:
            self.gui_coam_cu.choose_plan(plan_name)
        return self.gui_coam_cu.save_bts_configuration(save_configuration_type=save_type)

    @login_logout_GUI
    def get_cu_parameter_value_via_gui(self, dist_name, param_name, param_abbr, plan_name="CURRENT_PLAN",
                                       bts_id=0, du_id=0):
        """
        Get and return the value of specified parameter.
        :param plan_name: Name of the plan to choose.
        :param param_name: parameter name filter to locate target parameter.
        :param dist_name: dist name to locate the parameter. Please use MRBTS-{}/NRBTS-{} format.
        :param param_abbr: abbreviation of the parameter.
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: value of the specified parameter.
        """
        dist_name = self.adjust_dist_name(dist_name, bts_id, du_id)
        logging.info("Dist name:{}".format(dist_name))
        self.gui_coam_cu.choose_plan(plan_name=plan_name)
        current_value = self.gui_coam_cu.get_parameter_value(object_name=dist_name,
                                                             filter_param=param_name,
                                                             abbreviation=param_abbr)
        return current_value

    @login_logout_GUI
    def verify_cu_configuration_parameter_via_GUI(self, plan_name, dist_name, parameter,
                                                  abbreviation, value, bts_id=0):
        """
        Veirfy if given parameter of the CU configuration is equal to predicted value.

        :param plan_name:           Name of the plan to choose
        :type plan_name:            str
        :param dist_name:           Destination name of the object to be filtered from
        :type dist_name:            str
        :param parameter:           Full name of the parameter
        :type parameter:            str
        :param abbreviation:        Abbreviation of the parameter
        :type abbreviation:         str
        :param value:               Value to be compared
        :type value:                str
        :param bts_id:              BTS ID - related to Test Line configuration
        :type bts_id:               int
        """
        self.gui_coam_cu.choose_plan(plan_name=plan_name)
        current_value = self.gui_coam_cu.get_parameter_value(object_name=dist_name,
                                                             filter_param=parameter,
                                                             abbreviation=abbreviation)
        if current_value != value:
            raise InvalidParameterValue("Value of the parameter {} is equal to {}. Expected: {}"
                                        .format(parameter, current_value, value))

    @login_logout_GUI
    def modify_cu_configuration_parameters_via_GUI(self, dist_name, plan_name="CURRENT_PLAN", new_plan_name="NEW_PLAN",
                                                   change_params=None, change_abbreviations=None,
                                                   remove_params=None, remove_abbreviations=None,
                                                   values=None, delta_plan=False,
                                                   activate=True, bts_id=0):
        """
        Change and / or remove CU configuration parameter

        :param dist_name:           Destination name of the object to be filtered from
        :type dist_name:            str
        :param plan_name:           Name of the plan to create a copy of
        :type plan_name:            str
        :param new_plan_name:       Name of the new plan to be created
        :type new_plan_name:        str
        :param change_params:       List of the parameters to be modified
        :type change_params:        list
        :param change_abbreviations List of the abbreviations of parameters to be changed
        :type change_abbreviations  list
        :param remove_params:       List of the parameters to be removed
        :type remove_params:        list
        :param remove_abbreviations List of the abbreviations of parameters to be removed
        :type remove_abbreviations  list
        :param values:              List of the values to modified. Corresponds to the change_params
        :type values:               list
        :param delta_plan:          Flag for switching between ordinary plan creation and delta plan creation
        :type delta_plan:           bool
        :param activate:            If True, the plan will be activated after modification
        :type activate:             bool
        :param bts_id:              BTS ID - related to Test Line configuration
        :type bts_id:               int
        """
        if delta_plan:
            self._create_delta_plan_via_GUI_if_needed(plan_name=new_plan_name)
        else:
            self._create_plan_if_needed(plan_name=plan_name, new_plan_name=new_plan_name)
        self.gui_coam_cu.choose_plan(plan_name=new_plan_name)

        if change_params:
            for parameter, value, abbreviation in zip(change_params, values, change_abbreviations):
                self.gui_coam_cu.set_parameter_value(object_name=dist_name,
                                                     filter_param=parameter,
                                                     abbr=abbreviation,
                                                     new_value=value,
                                                     timeout=180)
                time.sleep(5)
        if remove_params:
            for parameter, abbreviation in zip(remove_params, remove_abbreviations):
                self.gui_coam_cu.delete_parameter(object_name=dist_name,
                                                  filter_param=parameter,
                                                  abbreviation=abbreviation,
                                                  timeout=180)
                time.sleep(5)
        if activate:
            self.gui_coam_cu.activate_plan()

