    def activate_cu_configuration_via_GUI(self, plan_name="NEW_PLAN", download_plan_without_activation=False,
                                          activate_plan_despite_reset=False, activate_plan_despite_cell_locking=False,
                                          inactive_configurations=False, bts_id=0):
        """
        Activates the chosen plan via GUI. Some parameters change the behaviour of the activation
        :param plan_name:                           Name of the plan to be chosen and activated
        :param download_plan_without_activation:    if True, download plan without activation will be selected
        :param activate_plan_despite_reset:         if True, activate plan despite of reset will be selected
        :param activate_plan_despite_cell_locking:  if True, activate plan despite of cell locking will be selected
        :param inactive_configurations:             if True, activated plan from Inactive configurations
        :param bts_id:                              BTS id - related to Test Line configuration
        :return:                                    Status of the activation
        """
        self.gui_coam_cu.choose_plan(plan_name=plan_name, inactive_configurations=inactive_configurations)
        status = self.gui_coam_cu.activate_plan(download_plan_without_activation=download_plan_without_activation,
                                                activate_plan_despite_reset=activate_plan_despite_reset,
                                                activate_plan_despite_cell_locking=activate_plan_despite_cell_locking)
        return status

