    def _set_single_cu_configuration_parameter_value_via_gui(self, dist_name, parameter_full_name=None,
                                                             new_value=None):
        """
        Method attempts to change a single parameter value on gNB CU to given value. If the value is already set
        method will not attempt to change it.

        :param dist_name:               Dist name path of the parameter, example: MRBTS-1/NRBTS-1/NRPMRNL-1
        :param parameter_full_name:     Full parameter name as seen via browser,
                                        example: NR F1AP Interface Report for CU per DU
        :param new_value:               New value of the parameter, example: 5min
        :return:                        True - if changes were made to the plan, False - if no changes were made
        """
        current_value = self.gui_coam_cu.get_parameter_value(object_name=dist_name, filter_param=parameter_full_name)
        logging.info("Current value of {}: {}".format(dist_name + "/" + parameter_full_name, str(current_value)))
        if current_value != new_value:
            self.gui_coam_cu.set_parameter_value(object_name=dist_name, filter_param=parameter_full_name,
                                                 new_value=new_value, timeout=60)
            time.sleep(3)
            return True
        return False

    @login_logout_GUI
    def fix_errors_with_uploaded_configuration(self, create_all_missing_mandatory_objects,
                                               create_all_missing_mandatory_parameters, timeout, choose_plan=True,
                                               validate_plan=True, bts_id=0):
        """Fix errors with uploaded scf file in webEM Cu, using create all missing MOs and parameters
        :param create_all_missing_mandatory_objects: boolean, if True, option will be selected
        :param create_all_missing_mandatory_parameters: boolean, if True option will be selected
        :param choose_plan: boolean, if True plan will be selected before errors fix
        :param validate_plan: boolean, if True plan will be validated before activation
        :param timeout: int, timeout for selenium to click element, by default 60
        :param bts_id: default id for Cu
        """
        if choose_plan:
            plan_name = self.gui_coam_cu.get_all_plans()
            plan_list = list(plan_name["Planned configurations:"]["plan"])
            plan_name = str(plan_list[-1]).strip("',u,[,]")
            logging.info("Name of plan to be activated: {}".format(plan_name))
            self.gui_coam_cu.choose_plan(plan_name=plan_name)

        self.gui_coam_cu.fix_errors(create_all_missing_mandatory_objects=create_all_missing_mandatory_objects,
                                    create_all_missing_mandatory_parameters=create_all_missing_mandatory_parameters,
                                    timeout=timeout)
        if validate_plan:
            self.gui_coam_cu.validate_plan()
